const colors={TASK:0xb99cff,ACCEPT:0x67e8f9,SUBMIT:0xffb86b,VOUCH:0x7cf7bb,NOTE:0x8398c9};
const canvas=document.querySelector('#scene'),renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(48,1,.1,100);camera.position.set(0,5.5,12);
