const starGeo=new THREE.BufferGeometry(),points=[];for(let i=0;i<1000;i++){const r=8+Math.random()*28,a=Math.random()*Math.PI*2,z=(Math.random()-.5)*24;points.push(Math.cos(a)*r,z,Math.sin(a)*r)}starGeo.setAttribute('position',new THREE.Float32BufferAttribute(points,3));scene.add(new THREE.Points(starGeo,new THREE.PointsMaterial({color:0x9fc5ff,size:.035,transparent:true,opacity:.72})));
const stations=[];
function labelSprite(text){const c=document.createElement('canvas');c.width=512;c.height=72;const x=c.getContext('2d');x.font='500 25px monospace';x.textAlign='center';x.fillStyle='#b8c9e8';x.fillText(text,256,44);const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(c),transparent:true,depthTest:false}));sprite.scale.set(3.8,.54,1);return sprite}
function makeStation(room,x,z,scale){const s=new THREE.Group();s.position.set(x,0,z);s.userData={room};const base=new THREE.Mesh(new THREE.CylinderGeometry(scale,scale*1.13,.38,8),new THREE.MeshStandardMaterial({color:0x0c1736,metalness:.7,roughness:.25}));base.position.y=.18;s.add(base);for(let i=0;i<5;i++){const floor=new THREE.Mesh(new THREE.BoxGeometry(scale*1.45,.44,scale*1.1),new THREE.MeshStandardMaterial({color:0x101d43,emissive:0x071128,metalness:.5,roughness:.35}));floor.position.y=.65+i*.52;floor.userData={room};s.add(floor)}const antenna=new THREE.Mesh(new THREE.ConeGeometry(.11,1.2,5),new THREE.MeshStandardMaterial({color:0x77dff5,emissive:0x1f8ca4}));antenna.position.y=3.45;s.add(antenna);const label=labelSprite(room);label.position.y=-.45;s.add(label);group.add(s);stations.push(s)}
makeStation(watchedRooms[0],0,0,2.15);makeStation(watchedRooms[1],-5.4,-2.1,1.25);makeStation(watchedRooms[2],5.1,-2.7,1.25);makeStation(watchedRooms[3],-4.5,3.2,1.02);makeStation(watchedRooms[4],4.5,3.5,1.1);
const trace=new THREE.Group();group.add(trace);let mode='live',liveRecords=[],revealed=0,playing=false,last=0,livePaused=false;const seen=new Set();
function classify(text=''){const kind=text.trim().split(/\s+/)[0]?.toUpperCase();return Object.hasOwn(colors,kind)?kind:'NOTE'}
function stationFor(room){return stations[Math.max(0,watchedRooms.indexOf(room))]||stations[0]}
function addTrace(record,index){const station=stationFor(record.room),seed=(Number(record.seq)||index)%29,angle=seed*.71,radius=1.3+(seed%5)*.17,target=station.position.clone();target.y=.8+(seed%5)*.48;const position=target.clone().add(new THREE.Vector3(Math.cos(angle)*radius,.05,Math.sin(angle)*radius)),color=colors[record.type]||colors.NOTE,dot=new THREE.Mesh(new THREE.SphereGeometry(.12,12,12),new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:2}));dot.position.copy(position);dot.userData={record};trace.add(dot);trace.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([position,target]),new THREE.LineBasicMaterial({color,transparent:true,opacity:.42})))}
function clearTrace(){while(trace.children.length)trace.remove(trace.children[0])}
function formatTime(ts){try{return new Date(ts).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}catch{return String(ts)}}
function inspect(record){const d=document.querySelector('#detail');d.replaceChildren();const e=document.createElement('div');e.className='eyebrow';e.textContent='EVIDENCE INSPECTOR';const h=document.createElement('h2');h.textContent=`${record.type} · sequence ${record.seq}`;const m=document.createElement('div');m.className='meta';m.textContent=`ROOM / ${record.room}   SOURCE / ${String(record.source||'unknown').slice(0,24)}\nOBSERVED / ${record.ts}`;const b=document.createElement('div');b.className='body';b.textContent=record.text;d.append(e,h,m,b)}
function draw(records,count=records.length){clearTrace();const start=Math.max(0,count-60);for(let i=start;i<count;i++)addTrace(records[i],i);const record=records[Math.max(0,count-1)];document.querySelector('#eventNumber').textContent=count;const s=document.querySelector('#scrubber');s.max=Math.max(0,records.length-1);s.value=Math.max(0,count-1);document.querySelector('#sequence').textContent=record?`SEQ ${record.seq} · ${record.room}`:(mode==='live'?'LIVE FEED':'SEQ —');document.querySelector('#timestamp').textContent=record?formatTime(record.ts):(mode==='live'?'WAITING':'READY');if(record)inspect(record)}
function setStatus(message,error=false){const el=document.querySelector('#status');el.classList.toggle('error',error);el.lastChild.textContent=` ${message}`}
function setMode(next){mode=next;playing=false;livePaused=false;document.querySelector('#liveMode').classList.toggle('active',mode==='live');document.querySelector('#replayMode').classList.toggle('active',mode==='replay');document.querySelector('#panelEyebrow').textContent=mode==='live'?'LIVE OBSERVATORY':'FLIGHT RECORDER';document.querySelector('#panelCopy').textContent=mode==='live'?'Five public rooms are sampled read-only. New messages become traces as they are observed.':'Scrub through the preserved Credence sequence, one captured record at a time.';document.querySelector('#eventLabel').textContent=mode==='live'?' live observations':' / 16 records revealed';document.querySelector('#confidence').textContent=mode==='live'?'Public, world-writable data · content is untrusted · activity does not prove causality or settlement':'Recorded observation · no claim of causality or settlement';document.querySelector('#play').textContent='▶';if(mode==='live')draw(liveRecords);else{revealed=0;draw(replayRecords,0)}}
async function readRoom(room,initial=false){const previous=[...seen].filter(k=>k.startsWith(`${room}:`)).map(k=>Number(k.split(':')[1])).sort((a,b)=>b-a)[0],params=new URLSearchParams({format:'json',limit:initial?'10':'30'});if(!initial&&previous)params.set('since',String(previous));const response=await fetch(`https://technocore.chat/r/${encodeURIComponent(room)}?${params}`,{cache:'no-store'});if(!response.ok)throw new Error(`${room}: HTTP ${response.status}`);const data=await response.json();for(const message of data.messages||[]){const key=`${room}:${message.seq}`;if(seen.has(key))continue;seen.add(key);liveRecords.push({seq:String(message.seq),ts:message.ts,type:classify(message.text),source:message.from||'anonymous',room,text:String(message.text||'')})}}
async function refreshLive(initial=false){if(livePaused)return;try{await Promise.all(watchedRooms.map(room=>readRoom(room,initial)));liveRecords.sort((a,b)=>new Date(a.ts)-new Date(b.ts));liveRecords=liveRecords.slice(-100);setStatus(`LIVE · ${watchedRooms.length} PUBLIC ROOMS · UPDATED ${formatTime(new Date())}`);if(mode==='live')draw(liveRecords)}catch(error){setStatus(`LIVE READ DELAYED · ${error.message}`,true)}}
function resize(){renderer.setSize(innerWidth,innerHeight,false);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}addEventListener('resize',resize);resize();
let drag=false,px=0,py=0;canvas.addEventListener('pointerdown',e=>{drag=true;px=e.clientX;py=e.clientY});addEventListener('pointerup',()=>drag=false);addEventListener('pointermove',e=>{if(drag){group.rotation.y+=(e.clientX-px)*.006;group.rotation.x=Math.max(-.45,Math.min(.35,group.rotation.x+(e.clientY-py)*.004));px=e.clientX;py=e.clientY}});canvas.addEventListener('wheel',e=>{camera.position.z=Math.max(7,Math.min(19,camera.position.z+e.deltaY*.009))},{passive:true});canvas.addEventListener('click',e=>{pointer.x=e.clientX/innerWidth*2-1;pointer.y=-(e.clientY/innerHeight)*2+1;ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(trace.children);if(hit[0]?.object.userData.record)inspect(hit[0].object.userData.record)});
document.querySelector('#scrubber').addEventListener('input',e=>{const records=mode==='live'?liveRecords:replayRecords;playing=false;document.querySelector('#play').textContent='▶';revealed=Number(e.target.value)+1;draw(records,revealed)});document.querySelector('#play').onclick=()=>{if(mode==='live'){livePaused=!livePaused;document.querySelector('#play').textContent=livePaused?'▶':'Ⅱ';setStatus(livePaused?'LIVE FEED PAUSED':'LIVE FEED RESUMED');if(!livePaused)refreshLive()}else{playing=!playing;document.querySelector('#play').textContent=playing?'Ⅱ':'▶'}};document.querySelector('#reset').onclick=()=>{if(mode==='live'){liveRecords=[];seen.clear();draw([]);refreshLive(true)}else{playing=false;revealed=0;draw(replayRecords,0)}};document.querySelector('#liveMode').onclick=()=>setMode('live');document.querySelector('#replayMode').onclick=()=>setMode('replay');
function animate(t){requestAnimationFrame(animate);group.rotation.y+=.0007;if(mode==='replay'&&playing&&t-last>720){last=t;if(revealed<replayRecords.length){revealed++;draw(replayRecords,revealed)}else{playing=false;document.querySelector('#play').textContent='▶'}}for(const child of trace.children)if(child.isMesh)child.scale.setScalar(1+Math.sin(t*.008+child.position.x)*.13);renderer.render(scene,camera)}
